-- Generated by `make db-migration` from schema.prisma. Review before applying.
-- Explicit transaction: Prisma does not make migrations atomic on PostgreSQL.
-- Hand-written SQL (RLS policies, CHECK constraints, functions) goes ABOVE the final COMMIT.
BEGIN;

-- Security review fix: without a ceiling, a delivery that crashes its worker (or keeps failing)
-- was re-claimed forever. Rows at the ceiling stay for inspection; the service marks them terminal.
-- CREATE OR REPLACE keeps the owner and the EXECUTE grant.
CREATE OR REPLACE FUNCTION claim_notification_deliveries(p_batch_size integer, p_lease_seconds integer DEFAULT 60)
RETURNS TABLE (organization_id uuid, delivery_id uuid)
LANGUAGE sql VOLATILE SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
  WITH due AS (
    SELECT d.id
    FROM notifications.notification_deliveries d
    WHERE d.next_attempt_at <= now()
      AND (d.status IN ('pending', 'failed') OR (d.status = 'sending' AND d.locked_until < now()))
      AND d.attempt_count < 20  -- poison-message ceiling: never re-claimed after 20 attempts
    ORDER BY d.next_attempt_at
    LIMIT LEAST(GREATEST(p_batch_size, 1), 500)
    FOR UPDATE SKIP LOCKED
  )
  UPDATE notifications.notification_deliveries d
  SET status = 'sending',
      locked_until = now() + make_interval(secs => LEAST(GREATEST(p_lease_seconds, 5), 900)),
      attempt_count = d.attempt_count + 1,
      updated_at = now()
  FROM due
  WHERE d.id = due.id
  RETURNING d.organization_id, d.id;
$$;

COMMIT;
